from decimal import Decimal, getcontext, ROUND_HALF_UP, ROUND_DOWN

getcontext().prec = 80


def _q(value, scale, rounded):
    exp = Decimal(1).scaleb(-scale)
    return value.quantize(exp, rounding=ROUND_HALF_UP if rounded else ROUND_DOWN)


def _fit(value, int_digits, scale, rounded=False, signed=True):
    """Ajusta un valor a un campo PIC: redondeo/truncamiento a la escala
    y truncamiento por la izquierda de los dígitos enteros excedentes."""
    v = _q(value, scale, rounded)
    neg = v < 0
    a = abs(v)
    modulus = Decimal(10) ** int_digits
    a = a % modulus
    a = _q(a, scale, False)
    if neg and signed:
        return -a
    return a


def _fmt(value, scale):
    if scale == 0:
        return str(int(value))
    return str(_q(value, scale, False))


def _to_int_field(s, digits):
    # Campo PIC 9(n) sin signo: se descartan decimales y signo, se trunca por la izquierda
    d = Decimal(str(s).strip())
    d = abs(d).to_integral_value(rounding=ROUND_DOWN)
    return int(d) % (10 ** digits)


def run(inp: dict) -> dict:
    # Campos de entrada (LOAN-REQUEST)
    principal = _fit(Decimal(str(inp.get("principal", "0")).strip()), 9, 2)  # S9(9)V99 COMP-3
    term_months = _to_int_field(inp.get("term_months", "0"), 3)              # 9(3)
    credit_score = _to_int_field(inp.get("credit_score", "0"), 3)            # 9(3)
    customer_age = _to_int_field(inp.get("customer_age", "0"), 3)            # 9(3)

    # READ-REQUEST: inicialización de LOAN-RESULT
    status = ""
    error_code = ""
    annual_rate = Decimal("0")          # 9V9(4)
    monthly_payment = Decimal("0")      # S9(9)V99
    insurance = Decimal("0")            # S9(7)V99
    total_interest = Decimal("0")       # S9(9)V99
    total_paid = Decimal("0")           # S9(9)V99

    def out():
        return {
            "status": status,
            "error_code": error_code,
            "annual_rate": _fmt(annual_rate, 4),
            "monthly_payment": _fmt(monthly_payment, 2),
            "insurance": _fmt(insurance, 2),
            "total_interest": _fmt(total_interest, 2),
            "total_paid": _fmt(total_paid, 2),
        }

    # VALIDATE-INPUT
    if principal < Decimal("1000.00") or principal > Decimal("500000.00"):
        status = "REJECTED"
        error_code = "E01"
    else:
        if term_months < 6 or term_months > 360:
            status = "REJECTED"
            error_code = "E02"
        else:
            ws_term_years = (term_months // 12) % 1000            # DIVIDE GIVING 9(3): truncamiento
            ws_maturity_age = (customer_age + ws_term_years) % 1000  # COMPUTE sin ROUNDED a 9(3)
            if ws_maturity_age > 75:
                status = "REJECTED"
                error_code = "E03"

    if status == "REJECTED":
        return out()  # ERROR-EXIT

    # DETERMINE-RATE
    if credit_score >= 750:
        annual_rate = Decimal("0.0899")
    elif credit_score >= 650:
        annual_rate = Decimal("0.1299")
    elif credit_score >= 550:
        annual_rate = Decimal("0.1899")
    else:
        status = "REJECTED"
        error_code = "E04"

    if status != "REJECTED":
        if credit_score >= 800 and term_months <= 60:
            annual_rate = _fit(annual_rate - Decimal("0.0025"), 1, 4, signed=False)
        if term_months > 120:
            annual_rate = _fit(annual_rate + Decimal("0.0050"), 1, 4, signed=False)

    if status == "REJECTED":
        return out()  # ERROR-EXIT

    # CALC-PAYMENT
    ws_rate_monthly = _fit(annual_rate / Decimal(12), 1, 9, rounded=True, signed=False)   # 9V9(9)
    ws_factor = _fit((Decimal(1) + ws_rate_monthly) ** term_months, 7, 9,
                     rounded=True, signed=False)                                       # 9(7)V9(9)
    monthly_payment = _fit(principal * ws_rate_monthly * ws_factor / (ws_factor - Decimal(1)),
                           9, 2, rounded=True)

    # CALC-INSURANCE
    if customer_age < 40:
        ws_ins_rate = Decimal("0.00035")
    elif customer_age < 60:
        ws_ins_rate = Decimal("0.00055")
    else:
        ws_ins_rate = Decimal("0.00095")
    insurance = _fit(principal * ws_ins_rate, 7, 2, rounded=True)

    # CALC-TOTALS (sin ROUNDED -> truncamiento)
    total_interest = _fit(monthly_payment * term_months - principal, 9, 2)
    total_paid = _fit((monthly_payment + insurance) * term_months, 9, 2)

    status = "APPROVED"
    # WRITE-AUDIT (EXEC SQL) no afecta las salidas: se omite
    return out()
